package edu.sc.servicedemo; import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import java.time.*; import java.util.*; @RestController @RequestMapping("/api") @CrossOrigin(origins="http://localhost:3000") class Api { final RequestRepo requests; final UserRepo users; Api(RequestRepo r,UserRepo u){requests=r;users=u;} record Login(String username,String password){} record RequestInput(String title,String details,LocalDate scheduledFor){} @PostMapping("/login") Map<String,String> login(@RequestBody Login l){User u=users.findByUsername(l.username()).filter(x->x.password.equals(l.password())).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED)); return Map.of("token","demo-jwt-token","username",u.username);}@GetMapping("/requests") List<ServiceRequest> all(@RequestParam(required=false) String status){return status==null?requests.findAll():requests.findByStatus(status);}@PostMapping("/requests") ServiceRequest add(@RequestBody RequestInput i){User u=users.findByUsername("demo").orElseThrow(); ServiceRequest r=new ServiceRequest();r.title=i.title();r.details=i.details();r.scheduledFor=i.scheduledFor();r.user=u;return requests.save(r);}@PatchMapping("/requests/{id}/complete") ServiceRequest complete(@PathVariable Long id){ServiceRequest r=requests.findById(id).orElseThrow();r.status="COMPLETE";return requests.save(r);}@DeleteMapping("/requests/{id}") void delete(@PathVariable Long id){requests.deleteById(id);} }
